import { toJsonEnvelope, toJsonValue } from "../protocol/envelope.js";
import { createClient } from "./client.js";
/** Consume an assembled boundary in process through the ordinary client contract. */
export function createLocalClient(options) {
    return createClient({
        ...(options.validateResponse === undefined
            ? {}
            : { validateResponse: options.validateResponse }),
        transport: async (request) => toJsonEnvelope(await options.invoker.invoke(request.path, toJsonValue(request.input), {
            signal: request.signal,
            timeoutMs: request.timeoutMs,
            correlationId: request.correlationId,
        })),
    });
}
